PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','editor','sales')),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
CREATE TABLE IF NOT EXISTS locales(code TEXT PRIMARY KEY,native_name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO locales VALUES('de','Deutsch',1,0),('en','English',1,1),('tr','Türkçe',1,2);
CREATE TABLE IF NOT EXISTS contents(id TEXT PRIMARY KEY,type TEXT NOT NULL CHECK(type IN ('article','news','project')),category TEXT NOT NULL DEFAULT 'software',source_locale TEXT NOT NULL DEFAULT 'de',cover_id TEXT,is_concept INTEGER NOT NULL DEFAULT 0,featured INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0,project_url TEXT NOT NULL DEFAULT '',technologies TEXT NOT NULL DEFAULT '[]',gallery TEXT NOT NULL DEFAULT '[]',provider TEXT,external_id TEXT,archived INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(provider,external_id));
CREATE TABLE IF NOT EXISTS translations(id TEXT PRIMARY KEY,content_id TEXT NOT NULL REFERENCES contents(id) ON DELETE CASCADE,locale TEXT NOT NULL REFERENCES locales(code),title TEXT NOT NULL,slug TEXT NOT NULL,excerpt TEXT NOT NULL DEFAULT '',body TEXT NOT NULL DEFAULT '',problem TEXT NOT NULL DEFAULT '',solution TEXT NOT NULL DEFAULT '',deliverables TEXT NOT NULL DEFAULT '',cover_alt TEXT NOT NULL DEFAULT '',meta_title TEXT NOT NULL DEFAULT '',meta_description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')),published_at TEXT,updated_at TEXT NOT NULL,UNIQUE(content_id,locale),UNIQUE(locale,slug));
CREATE INDEX IF NOT EXISTS translations_public ON translations(locale,status,published_at);
CREATE TABLE IF NOT EXISTS redirects(locale TEXT NOT NULL,section TEXT NOT NULL,old_slug TEXT NOT NULL,content_id TEXT NOT NULL REFERENCES contents(id) ON DELETE CASCADE,PRIMARY KEY(locale,section,old_slug));
CREATE TABLE IF NOT EXISTS form_versions(id TEXT PRIMARY KEY,version_number INTEGER NOT NULL UNIQUE,status TEXT NOT NULL CHECK(status IN ('draft','published','retired')),schema TEXT NOT NULL,created_at TEXT NOT NULL,published_at TEXT,retired_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_published_form ON form_versions(status) WHERE status='published';
CREATE TABLE IF NOT EXISTS enquiries(id TEXT PRIMARY KEY,reference TEXT NOT NULL UNIQUE,idempotency_key TEXT NOT NULL UNIQUE,form_version_id TEXT NOT NULL REFERENCES form_versions(id),locale TEXT NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL,company TEXT NOT NULL DEFAULT '',service TEXT NOT NULL DEFAULT '',budget TEXT NOT NULL DEFAULT '',answers TEXT NOT NULL,schema_snapshot TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',assigned_to TEXT REFERENCES users(id),created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS enquiries_created ON enquiries(created_at DESC);
CREATE TABLE IF NOT EXISTS enquiry_notes(id TEXT PRIMARY KEY,enquiry_id TEXT NOT NULL REFERENCES enquiries(id) ON DELETE CASCADE,author_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS enquiry_history(id TEXT PRIMARY KEY,enquiry_id TEXT NOT NULL REFERENCES enquiries(id) ON DELETE CASCADE,actor_id TEXT REFERENCES users(id),event TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS files(id TEXT PRIMARY KEY,enquiry_id TEXT REFERENCES enquiries(id) ON DELETE CASCADE,field_key TEXT,name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN ('public','private')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS file_chunks(file_id TEXT NOT NULL REFERENCES files(id) ON DELETE CASCADE,part INTEGER NOT NULL,data BLOB NOT NULL,PRIMARY KEY(file_id,part));
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,hits INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS api_tokens(id TEXT PRIMARY KEY,name TEXT NOT NULL,hash TEXT NOT NULL UNIQUE,scopes TEXT NOT NULL,created_at TEXT NOT NULL,last_used_at TEXT);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,actor TEXT,action TEXT NOT NULL,subject TEXT,created_at TEXT NOT NULL);
